import azure.cognitiveservices.speech as speechsdk

def stream_with_language():
    speech_config = speechsdk.SpeechConfig(subscription="YOUR_SUBSCRIPTION_KEY", region="YOUR_SERVICE_REGION")
    speech_config.speech_recognition_language="en-US"
    audio_config = speechsdk.audio.AudioConfig(use_default_microphone=True)
    speech_recognizer = speechsdk.SpeechRecognizer(speech_config=speech_config, audio_config=audio_config)

    speech_recognizer.recognized.connect(lambda evt: handle_partial_results(evt))

    print("Speak into your microphone.")
    result = speech_recognizer.recognize_once()

    if result.reason == speechsdk.ResultReason.RecognizedSpeech:
        print("Recognized: {}".format(result.text))
    elif result.reason == speechsdk.ResultReason.NoMatch:
        print("No speech could be recognized.")
    elif result.reason == speechsdk.ResultReason.Canceled:
        cancellation_details = result.cancellation_details
        print("Speech Recognition canceled: {}".format(cancellation_details.reason))
        if cancellation_details.reason == speechsdk.CancellationReason.Error:
            print("Error details: {}".format(cancellation_details.error_details))

if __name__ == "__main__":
    stream_with_language()

import os
import azure.cognitiveservices.speech as speechsdk

def get_speech_config():
    subscription_key = os.getenv('SPEECH_SUBSCRIPTION_KEY')
    region = os.getenv('SPEECH_SERVICE_REGION')
    return speechsdk.SpeechConfig(subscription=subscription_key, region=region)

def get_audio_config(use_default_microphone=True):
    return speechsdk.audio.AudioConfig(use_default_microphone=use_default_microphone)

def normalize_speech_recognition_result(result):
    if result.reason == speechsdk.ResultReason.RecognizedSpeech:
        return result.text
    elif result.reason == speechsdk.ResultReason.NoMatch:
        return "No speech could be recognized."
    elif result.reason == speechsdk.ResultReason.Canceled:
        cancellation_details = result.cancellation_details
        return "Speech Recognition canceled: {}".format(cancellation_details.reason)
